impl Wedge<MultiVector> for AntiPlane {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32       11       24        0        0
    //    simd2        0        2        0      N/A
    //    simd3        7        9        0      N/A
    //    simd4        3        3        0      N/A
    // Totals...
    // yes simd       21       38        0      N/A
    //  no simd       44       67        0        0
    fn wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([0.0, (self[e1] * other[e4235]) + (self[e2] * other[e4315]) + (self[e3] * other[e4125]) + (self[e5] * other[e1234])]),
            // e1, e2, e3, e4
            (Simd32x3::from(other[scalar]) * self.group0().xyz()).with_w(0.0),
            // e5
            self[e5] * other[scalar],
            // e41, e42, e43, e45
            Simd32x4::from(other[e4] * -1.0) * self.group0(),
            // e15, e25, e35
            (Simd32x3::from(other[e5]) * self.group0().xyz()) - (Simd32x3::from(self[e5]) * other.group1().xyz()),
            // e23, e31, e12
            (self.group0().yzx() * other.group1().zxy()) + Simd32x2::from(0.0).with_z((self[e2] * other[e1]) * -1.0) - (self.group0().zx() * other.group1().yz()).with_z(0.0),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(-(self[e2] * other[e31]) - (self[e3] * other[e12])) + (Simd32x3::from(self[e5]) * other.group3().xyz()).with_w(0.0)
                - (self.group0().xyzx() * Simd32x3::from(other[e45]).with_w(other[e23])),
            // e423, e431, e412
            (self.group0().zxy() * other.group3().yzx()) + Simd32x2::from(0.0).with_z((self[e1] * other[e42]) * -1.0) - (self.group0().yz() * other.group3().zx()).with_z(0.0),
            // e235, e315, e125
            (Simd32x3::from(self[e5]) * other.group5()) + (other.group4().zxy() * self.group0().yzx()) - (other.group4().yzx() * self.group0().zxy()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                (self[e2] * other[e431]) + (self[e3] * other[e412]),
                -(self[e2] * other[e435]) - (self[e5] * other[e423]),
                -(self[e3] * other[e415]) - (self[e5] * other[e431]),
                -(self[e1] * other[e425]) - (self[e5] * other[e412]),
            ]) + (Simd32x4::from([other[e423], other[e425], other[e435], other[e415]]) * self.group0().xzxy()),
            // e3215
            -(self[e1] * other[e235]) - (self[e2] * other[e315]) - (self[e3] * other[e125]) - (self[e5] * other[e321]),
        )
    }
}
