impl Wedge<MultiVector> for DualNum {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        1        3        0        0
    //    simd3        0        2        0      N/A
    //    simd4        0        2        0      N/A
    // Totals...
    // yes simd        1        7        0      N/A
    //  no simd        1       17        0        0
    fn wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([0.0, (self[e4] * other[e3215]) + (self[e12345] * other[scalar])]),
            // e1, e2, e3, e4
            Simd32x3::from(0.0).with_w(self[e4] * other[scalar]),
            // e5
            0.0,
            // e41, e42, e43, e45
            Simd32x4::from(self[e4]) * other.group1().xyz().with_w(other[e5]),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            (Simd32x3::from(self[e4]) * other.group4()).with_w(0.0),
            // e423, e431, e412
            Simd32x3::from(self[e4]) * other.group5(),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(self[e4]) * Simd32x4::from([other[e321], other[e235], other[e315], other[e125]]),
            // e3215
            0.0,
        )
    }
}
