impl Wedge<MultiVector> for FlectorOnOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        6       12        0        0
    //    simd3        0        1        0      N/A
    // Totals...
    // yes simd        6       13        0      N/A
    //  no simd        6       15        0        0
    fn wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([0.0, (self[e4235] * other[e1]) + (self[e4315] * other[e2]) + (self[e4125] * other[e3]) - (self[e45] * other[e321])]),
            // e1, e2, e3, e4
            Simd32x4::from(0.0),
            // e5
            0.0,
            // e41, e42, e43, e45
            Simd32x3::from(0.0).with_w(self[e45] * other[scalar]),
            // e15, e25, e35
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            (Simd32x3::from(self[e45] * -1.0) * other.group1().xyz()).with_w(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                0.0,
                (self[e45] * other[e23]) + (self[e4235] * other[scalar]),
                (self[e45] * other[e31]) + (self[e4315] * other[scalar]),
                (self[e45] * other[e12]) + (self[e4125] * other[scalar]),
            ]),
            // e3215
            0.0,
        )
    }
}
