    //  no simd       60       82        0        0
    fn wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                0.0,
                (other[e1234] * self[e5]) + (other[e4235] * self[e1]) + (other[e4315] * self[e2]) + (other[e4125] * self[e3]) + (other[e3215] * self[e4]),
            ]),
            // e1, e2, e3, e4
            Simd32x4::from(other[scalar]) * self.group0(),
            // e5
            other[scalar] * self[e5],
            // e41, e42, e43, e45
            (Simd32x4::from(self[e4]) * other.group1().xyz().with_w(other[e5])) - (Simd32x4::from(other[e4]) * self.group0().xyz().with_w(self[e5])),
            // e15, e25, e35
            (Simd32x3::from(other[e5]) * self.group0().xyz()) - (Simd32x3::from(self[e5]) * other.group1().xyz()),
            // e23, e31, e12
            (other.group1().zxy() * self.group0().yzx()) + Simd32x2::from(0.0).with_z((other[e1] * self[e2]) * -1.0) - (other.group1().yz() * self.group0().zx()).with_z(0.0),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(-(other[e31] * self[e2]) - (other[e12] * self[e3]))
                + (Simd32x3::from(self[e4]) * other.group4()).with_w(0.0)
                + (Simd32x3::from(self[e5]) * other.group3().xyz()).with_w(0.0)
                - (self.group0().xyzx() * Simd32x3::from(other[e45]).with_w(other[e23])),
            // e423, e431, e412
            (Simd32x3::from(self[e4]) * other.group5()) + (other.group3().yzx() * self.group0().zxy()) + Simd32x2::from(0.0).with_z((other[e42] * self[e1]) * -1.0)
                - (other.group3().zx() * self.group0().yz()).with_z(0.0),
            // e235, e315, e125
            (Simd32x3::from(self[e5]) * other.group5()) + (other.group4().zxy() * self.group0().yzx()) - (other.group4().yzx() * self.group0().zxy()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                (other[e431] * self[e2]) + (other[e412] * self[e3]),
                -(other[e435] * self[e2]) - (other[e423] * self[e5]),
                -(other[e415] * self[e3]) - (other[e431] * self[e5]),
                -(other[e425] * self[e1]) - (other[e412] * self[e5]),
            ]) + (Simd32x4::from(self[e4]) * Simd32x4::from([other[e321], other[e235], other[e315], other[e125]]))
                + (Simd32x4::from([other[e423], other[e425], other[e435], other[e415]]) * self.group0().xzxy()),
            // e3215
            -(other[e321] * self[e5]) - (other[e235] * self[e1]) - (other[e315] * self[e2]) - (other[e125] * self[e3]),
        )
    }
