impl Wedge<MultiVector> for RoundPointAtOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        5       17        0        0
    //    simd2        0        1        0      N/A
    //    simd3        1        5        0      N/A
    // Totals...
    // yes simd        6       23        0      N/A
    //  no simd        8       34        0        0
    fn wedge(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([0.0, (other[e1234] * self[e5]) + (other[e3215] * self[e4])]),
            // e1, e2, e3, e4
            Simd32x3::from(0.0).with_w(other[scalar] * self[e4]),
            // e5
            other[scalar] * self[e5],
            // e41, e42, e43, e45
            (Simd32x2::from(self[e4]) * other.group1().xy()).with_zw(other[e3] * self[e4], (other[e5] * self[e4]) - (other[e4] * self[e5])),
            // e15, e25, e35
            Simd32x3::from(self[e5] * -1.0) * other.group1().xyz(),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            ((Simd32x3::from(self[e4]) * other.group4()) + (Simd32x3::from(self[e5]) * other.group3().xyz())).with_w(0.0),
            // e423, e431, e412
            Simd32x3::from(self[e4]) * other.group5(),
            // e235, e315, e125
            Simd32x3::from(self[e5]) * other.group5(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                other[e321] * self[e4],
                (other[e235] * self[e4]) - (other[e423] * self[e5]),
                (other[e315] * self[e4]) - (other[e431] * self[e5]),
                (other[e125] * self[e4]) - (other[e412] * self[e5]),
            ]),
            // e3215
            other[e321] * self[e5] * -1.0,
        )
    }
}
